// sel-fill-air v1
// Parche: al pulsar un numero de ranura con la herramienta Seleccionar
// y una caja confirmada, rellena TODA la caja (aire incluido) en vez de
// reemplazar solo los bloques solidos.
//
// API:
//   game.selFillAir.on()      activa el parche
//   game.selFillAir.off()     restaura el comportamiento original
//   game.selFillAir.estado()  info
//
(() => {
'use strict';

const origFillId = window.mcSelectFillId;
if(typeof origFillId !== 'function') throw new Error('sel-fill-air: no encuentro mcSelectFillId');

let activo = false;
let stats = { ops: 0 };

function mcSelForEachConAire(fn){
  const cajas = mc.selCajas; if(!cajas || !cajas.length) return;
  const vistas = cajas.length > 1 ? new Set() : null;
  for(let ci = 0; ci < cajas.length; ci++){
    const s = cajas[ci];
    const x0 = Math.min(s.a[0], s.b[0]), x1 = Math.max(s.a[0], s.b[0]);
    const y0 = Math.min(s.a[1], s.b[1]), y1 = Math.max(s.a[1], s.b[1]);
    const z0 = Math.min(s.a[2], s.b[2]), z1 = Math.max(s.a[2], s.b[2]);
    for(let x = x0; x <= x1; x++) for(let y = y0; y <= y1; y++) for(let z = z0; z <= z1; z++){
      if(!mcInside(x, y, z)) continue;
      const i = mcIdx(x, y, z);
      if(vistas){ if(vistas.has(i)) continue; vistas.add(i); }
      const id = mc.grid[i];
      fn(x, y, z, id, ci);
    }
  }
}

function patchedFillId(id, yaHecha){
  if(mc.tool !== 'select' || !mc.selBox || !id) return false;
  const celdas = [];
  mcSelForEachConAire((x, y, z, before) => celdas.push([x, y, z, before]));
  if(!celdas.length){ toast('Nada que rellenar'); return true; }
  const edits = [];
  let desde = 0;
  if(yaHecha){ edits.push(yaHecha); desde = 1; }
  for(let n = desde; n < celdas.length; n++){
    const [x, y, z, before] = celdas[n];
    if(before === id) continue;
    mc.grid[mcIdx(x, y, z)] = id;
    mcDirty(x, y, z);
    mcGlowTocada(x, y, z);
    edits.push({x, y, z, before, after: id});
  }
  if(!edits.length){ toast('Nada que rellenar'); return true; }
  mcRemeshEdiciones(edits);
  mcPushHist({t: 'bb', edits});
  mcScheduleSave();
  toast(edits.length + ' bloque(s) rellenados con ' + mcNombreMat(mc.blockKey[id] || ''));
  stats.ops++;
  return true;
}

function instalar(){
  window.mcSelectFillId = patchedFillId;
  activo = true;
}

function desinstalar(){
  window.mcSelectFillId = origFillId;
  activo = false;
}

function estado(){
  const s = 'sel-fill-air: ' + (activo ? 'ACTIVO' : 'inactivo') + ' · ops: ' + stats.ops;
  console.log(s);
  return s;
}

const API = {
  on(){ if(!activo) instalar(); return 'sel-fill-air activado'; },
  off(){ if(activo) desinstalar(); return 'sel-fill-air desactivado'; },
  estado
};
game.selFillAir = API;
API.on();
})();
